# Generated by ChatGPT

import os
import sys
import pandas as pd


def merge_csv_files(folder_path, output_filename="merged_output.csv"):
    """
    Merge all CSV files in a given folder into a single CSV file.
    Adds a first column indicating the source filename (without .csv).

    Parameters:
        folder_path (str): Path to folder containing CSV files
        output_filename (str): Name of the merged output file
    """

    # Validate folder
    if not os.path.isdir(folder_path):
        raise NotADirectoryError(f"Folder does not exist: {folder_path}")

    # List all CSV files (case-insensitive)
    csv_files = [
        os.path.join(folder_path, f)
        for f in os.listdir(folder_path)
        if f.lower().endswith(".csv")
    ]

    if not csv_files:
        raise FileNotFoundError("No CSV files found in the specified folder.")

    print(f"Found {len(csv_files)} CSV files.")

    dataframes = []
    reference_columns = None

    for file_path in csv_files:
        filename = os.path.basename(file_path)
        file_stem = os.path.splitext(filename)[0]  # Remove .csv

        print(f"Reading: {file_path}")
        df = pd.read_csv(file_path)

        # Validate column structure
        if reference_columns is None:
            reference_columns = list(df.columns)
        else:
            if list(df.columns) != reference_columns:
                raise ValueError(
                    f"Column mismatch detected in file: {file_path}\n"
                    f"Expected: {reference_columns}\n"
                    f"Found: {list(df.columns)}"
                )

        # Insert source column as first column
        df.insert(0, "source_file", file_stem)

        dataframes.append(df)

    # Merge all DataFrames
    merged_df = pd.concat(dataframes, ignore_index=True)

    # Write output
    output_path = os.path.join(folder_path, output_filename)
    merged_df.to_csv(output_path, index=False)

    print(f"\nSuccessfully merged files into: {output_path}")
    print(f"Total rows: {len(merged_df)}")


if __name__ == "__main__":
    if len(sys.argv) < 2:
        print(f"Usage: python {sys.argv[0]} <folder_path>")
        sys.exit(1)

    merge_csv_files(sys.argv[1])

